scriptdefs
= LavaridgeTown_EventScript_RivalGiveGoGoggles
lockall
getplayerxy VAR_0x8008 VAR_0x8009
call_if_eq VAR_0x8008 9 LavaridgeTown_EventScript_RivalNoticePlayer
call_if_ne VAR_0x8008 9 LavaridgeTown_EventScript_RivalExitHerbShop
delay 20
checkplayergender
call_if_eq VAR_RESULT MALE LavaridgeTown_EventScript_PlayMayMusic
call_if_eq VAR_RESULT FEMALE LavaridgeTown_EventScript_PlayBrendanMusic
call_if_eq VAR_0x8008 9 LavaridgeTown_EventScript_RivalApproachPlayer1
call_if_ne VAR_0x8008 9 LavaridgeTown_EventScript_RivalApproachPlayer2
checkplayergender
goto_if_eq VAR_RESULT MALE LavaridgeTown_EventScript_MayGiveGoGoggles
goto_if_eq VAR_RESULT FEMALE LavaridgeTown_EventScript_BrendanGiveGoGoggles
end
= LavaridgeTown_EventScript_BrendanGiveGoGoggles
msgbox	BRENDAN: PLAYER, hey, lange nicht gesehen. Wie läuft's?Hmm… Das ist eine ordentliche Sammlung an ORDEN.Alles klar, dann. Das hier kannst du genauso gut haben.
giveitem ITEM_GO_GOGGLES
setflag FLAG_RECEIVED_GO_GOGGLES
msgbox	BRENDAN: Behalt die, falls du vorhast, in diese Wüste bei ROUTE 111 zu gehen.Es soll dort POKéMON geben, die ausschließlich in der Wüste leben. Halt mal Ausschau nach denen.Was mich angeht… Ich überlege, NORMAN, den ARENALEITER von PETALBURG, herauszufordern.Anders als du, PLAYER, sieht dein Vater aus, als wäre er wirklich hart.Bis bald!
goto LavaridgeTown_EventScript_RivalExit
end
= LavaridgeTown_EventScript_RivalExit
closemessage
removeobject LOCALID_LAVARIDGE_RIVAL
addobject LOCALID_LAVARIDGE_RIVAL_ON_BIKE
delay 30
call_if_eq VAR_0x8008 9 LavaridgeTown_EventScript_RivalExit1
call_if_ne VAR_0x8008 9 LavaridgeTown_EventScript_RivalExit2
removeobject LOCALID_LAVARIDGE_RIVAL_ON_BIKE
setvar VAR_LAVARIDGE_TOWN_STATE 2
clearflag FLAG_HIDE_MAP_NAME_POPUP
savebgm MUS_DUMMY
fadedefaultbgm
releaseall
end
= LavaridgeTown_EventScript_RivalExit2
applymovement LOCALID_LAVARIDGE_RIVAL_ON_BIKE LavaridgeTown_Movement_RivalExit2
waitmovement 0
return
= LavaridgeTown_EventScript_RivalExit1
applymovement LOCALID_PLAYER LavaridgeTown_Movement_PlayerWatchRivalExit
applymovement LOCALID_LAVARIDGE_RIVAL_ON_BIKE LavaridgeTown_Movement_RivalExit1
waitmovement 0
return
= LavaridgeTown_EventScript_MayGiveGoGoggles
msgbox	MAY: PLAYER! Lange nicht gesehen!Oh? Während ich die heißen Quellen besucht habe, hast du dir den LAVARIDGE-ARENAORDEN geholt.Du musst dir gute POKéMON zugelegt haben… Nein, ich glaube, du hast welche großgezogen.Ich denke, du kannst das hier gut gebrauchen.
giveitem ITEM_GO_GOGGLES
setflag FLAG_RECEIVED_GO_GOGGLES
msgbox	MAY: Mit dieser STAUBSCHUTZBRILLE hast du keine Probleme, durch die Wüste bei ROUTE 111 zu kommen.Aber wow, PLAYER… ARENEN herausfordern…Du strengst dich sicher so an, weil du nicht gegen mich verlieren willst!PLAYER, ich glaube, ich sollte deinen Vater in der PETALBURG-ARENA herausfordern.Bis dann!
goto LavaridgeTown_EventScript_RivalExit
end
= LavaridgeTown_EventScript_RivalApproachPlayer2
applymovement LOCALID_LAVARIDGE_RIVAL LavaridgeTown_Movement_RivalApproachPlayer2
waitmovement 0
return
= LavaridgeTown_EventScript_RivalApproachPlayer1
applymovement LOCALID_LAVARIDGE_RIVAL LavaridgeTown_Movement_RivalApproachPlayer1
waitmovement 0
return
= LavaridgeTown_EventScript_PlayBrendanMusic
playbgm MUS_ENCOUNTER_BRENDAN TRUE
return
= LavaridgeTown_EventScript_PlayMayMusic
playbgm MUS_ENCOUNTER_MAY TRUE
return
= LavaridgeTown_EventScript_RivalExitHerbShop
opendoor 12 15
waitdooranim
addobject LOCALID_LAVARIDGE_RIVAL
applymovement LOCALID_LAVARIDGE_RIVAL LavaridgeTown_Movement_RivalExitHerbShop
waitmovement 0
closedoor 12 15
waitdooranim
applymovement LOCALID_LAVARIDGE_RIVAL Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
playse SE_PIN
applymovement LOCALID_LAVARIDGE_RIVAL Common_Movement_ExclamationMark
waitmovement 0
applymovement LOCALID_LAVARIDGE_RIVAL Common_Movement_Delay48
waitmovement 0
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterRight
waitmovement 0
return
= LavaridgeTown_EventScript_RivalNoticePlayer
applymovement LOCALID_LAVARIDGE_RIVAL Common_Movement_WalkInPlaceFasterUp
waitmovement 0
playse SE_PIN
applymovement LOCALID_LAVARIDGE_RIVAL Common_Movement_ExclamationMark
waitmovement 0
applymovement LOCALID_LAVARIDGE_RIVAL Common_Movement_Delay48
waitmovement 0
return
= LavaridgeTown_HiddenItem_4_5
goto_if_set FLAG_HIDDEN_ITEM_LAVARIDGE_TOWN_ICE_HEAL LavaridgeTown_HiddenItem_4_5_Taken
finditem ITEM_ICE_HEAL
setflag FLAG_HIDDEN_ITEM_LAVARIDGE_TOWN_ICE_HEAL
end
= LavaridgeTown_HiddenItem_4_5_Taken
end
= LavaridgeTown_EventScript_HotSpringsTrigger
specialvar VAR_RESULT GetPlayerFacingDirection
goto_if_eq VAR_RESULT DIR_SOUTH LavaridgeTown_EventScript_EnteredHotSprings
end
= LavaridgeTown_EventScript_EnteredHotSprings
incrementgamestat GAME_STAT_ENTERED_HOT_SPRINGS
end
= LavaridgeTown_EventScript_EggWoman
lock
faceplayer
goto_if_set FLAG_RECEIVED_LAVARIDGE_EGG LavaridgeTown_EventScript_ReceivedEgg
msgboxyesno	I have here an EGG.I'd hoped to hatch it by covering it in hot sand by the hot springs. But that doesn't seem to be enough…I've heard it would be best if it were kept together with POKéMON and carried about.You are a TRAINER, yes? And your POKéMON radiate vitality.So, what say you? Will you take this EGG to hatch?
goto_if_eq VAR_RESULT NO LavaridgeTown_EventScript_DeclineEgg
getpartysize
goto_if_eq VAR_RESULT PARTY_SIZE LavaridgeTown_EventScript_NoRoomForEgg
msgbox	Schön! Ich hoffe, du läufst viel mit diesem EI hier herum!
setflag FLAG_RECEIVED_LAVARIDGE_EGG
playfanfare MUS_OBTAIN_ITEM
msgbox	PLAYER erhielt das EI.
waitfanfare
giveegg SPECIES_WYNAUT
release
end
= LavaridgeTown_EventScript_NoRoomForEgg
msgbox	Oh? Du hast zu viele POKéMON. Es ist kein Platz mehr für dieses EI…
release
end
= LavaridgeTown_EventScript_DeclineEgg
msgbox	Wie du wünschst, dann…Falls du es dir anders überlegst und dieses EI ausbrüten willst, bin ich hier.
release
end
= LavaridgeTown_EventScript_ReceivedEgg
msgbox	Hin und wieder findet man ein EI im POKéMON-HORT.Zumindest geht so das Gerücht.
release
end
= LavaridgeTown_EventScript_HotSpringsOldWoman2
msgbox	Sie behaupten, diese heißen Quellen würden Nervosität lindern, schmerzende Muskeln entspannen, Liebesprobleme lösen und Geld anziehen…
end
= LavaridgeTown_EventScript_HotSpringsOldWoman1
msgbox	Wenn Leute POKéMON in heiße Quellen setzen würden, könnte das echt seltsam werden.Es könnte ein elektrisches Bad sein, oder ein Schaumbad, oder sogar ein Lavabad…
end
= LavaridgeTown_EventScript_Twin
msgbox	Ich bade jeden Tag in den heißen Quellen.Ich will eine schöne und starke ARENALEITERIN wie FLANNERY werden.
end
= LavaridgeTown_EventScript_OldMan
msgbox	In diesem heißen Sand vergraben zu sein, ist… Seufz…So warm und himmlisch…Eh? Gyaah! Autsch!Ein POKéMON hat mich in den Hintern gezwickt!
end
